pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testRegression_property() public {
        TokenTracker tracker = new TokenTracker();

        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);

        c.transfer(from, address(tracker), tos, 100);

        bool wasCalled = tracker.called();
        assertTrue(wasCalled, "transferFrom should have been called exactly once");
    }
}

contract TokenTracker {
    bool public called;
    function transferFrom(address, address, uint256) external returns (bool) {
        called = true;
        return true;
    }
}
